def _dt(value):
    if not value:
        return None
    parsed = datetime.strptime(value, "%Y-%m-%d %H:%M:%S")
    if timezone.is_naive(parsed):
        return timezone.make_aware(parsed, timezone.get_current_timezone())
    return parsed


def load_lms_transcript(student_id=STUDENT_ID):
    created = 0
    updated = 0
    for row in ROWS:
        (
            lms_id, code, credits, alpha, numeral, total, ru, kz, en, exam,
            course, term, type_, mark_id, query_id, modified, subject_id,
            group_type_id, traditional_mark, created_at, tup_subject_id,
        ) = row
        defaults = {
            "student_id": student_id,
            "subject_code": code,
            "credits": credits,
            "alpha_mark": alpha or "",
            "numeral_mark": numeral,
            "total_mark": total,
            "subject_name_ru": ru,
            "subject_name_kz": kz,
            "subject_name_en": en,
            "exam_mark": exam,
            "course_number": course,
            "term": term,
            "type": type_,
            "mark_id": mark_id,
            "query_id": query_id,
            "modified": _dt(modified),
            "subject_id": subject_id,
            "group_type_id": group_type_id,
            "traditional_mark": traditional_mark,
            "created": _dt(created_at),
            "tup_subject_id": tup_subject_id,
            "code_en": code,
            "code_ru": code,
            "subject_study_language": 2,
            "subject_type": 7,
        }
        _, was_created = Transcript.objects.update_or_create(
            lms_id=lms_id,
            defaults=defaults,
        )
        if was_created:
            created += 1
        else:
            updated += 1
    return created, updated
